import type { ReactNode } from 'react';
import { formatFigure, useLocale } from './locale';

/** Shows a figure (an amount, due figure, total, rate, share or cut) in the signed-in user's locale.
 *  Wrap the content of every element that shows one; text that is not a figure is shown as it is. */
export function Fig({ children }: { children: ReactNode }) {
  const locale = useLocale();
  if (typeof children === 'string') return <>{formatFigure(children, locale)}</>;
  if (typeof children === 'number') return <>{formatFigure(String(children), locale)}</>;
  return <>{children}</>;
}
package net.officefloor.hq.app.period;

import java.util.Map;

/** A period on a sheet: its name and its from and to dates (yyyy-MM-dd), both inclusive, whether it
 *  is closed and, once closed, its due-total fixed at that moment (two decimals) and each person's
 *  due-total for it fixed then too, by person id (a person not in it shows 0.00). A soft-closed period
 *  ({@code soft}, not {@code closed}) has its figures fixed the same way, but claims due by a day in it can
 *  still be added and changed. Its cap (null: none) is the most OPEN or PENDING claims a person may
 *  have in it. Once fixed, each person's carried figure for it is fixed then too ({@code personCarried}).
 *  Each person's opening balance for it (pasted, added up), by person id ({@code personOpenings}); it is
 *  added to their live carried figure, and fixed into it when the period is closed or soft-closed.
 *  A locked period (only a steward locks and unlocks it) cannot be reopened. */
public record Period(String sheetId, String name, String from, String to, boolean closed,
        String closedTotal, Map<Long, String> personTotals, boolean soft, Integer cap,
        Map<Long, String> personCarried, Map<Long, String> personOpenings, boolean locked) {

    /** Whether its figures are fixed: closed or soft-closed. */
    public boolean fixed() {
        return closed || soft;
    }

    /** Whether the date (yyyy-MM-dd) falls inside it. */
    public boolean contains(String date) {
        return from.compareTo(date) <= 0 && date.compareTo(to) <= 0;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.pool.PoolRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class).toString(),
            rs.getObject("to_date", LocalDate.class).toString(), rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null
                    : rs.getBigDecimal("closed_total").setScale(2).toPlainString(), Map.of(),
            rs.getBoolean("soft_closed"), (Integer) rs.getObject("claim_cap", Integer.class), Map.of(), Map.of(),
            rs.getBoolean("locked"));

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total, soft_closed, claim_cap, locked FROM period ";

    private final JdbcTemplate jdbc;
    private final PoolRepository pools;

    public PeriodRepository(JdbcTemplate jdbc, PoolRepository pools) {
        this.jdbc = jdbc;
        this.pools = pools;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query(COLUMNS + "WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId).stream()
                .map(this::withPersonTotals).map(this::withOpenings).toList();
    }

    /** The period with each person's due-total and carried figure fixed when it was closed. */
    private Period withPersonTotals(Period p) {
        if (!p.fixed()) return p;
        Map<Long, String> totals = new LinkedHashMap<>();
        Map<Long, String> carried = new LinkedHashMap<>();
        jdbc.query("SELECT t.person_id, t.total, t.carried FROM period_person_total t JOIN period p ON p.id = t.period_id "
                + "WHERE p.sheet_id = ? AND p.name = ? ORDER BY t.person_id",
                rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total").setScale(2).toPlainString());
                    carried.put(rs.getLong("person_id"), rs.getBigDecimal("carried").setScale(2).toPlainString());
                },
                p.sheetId(), p.name());
        return new Period(p.sheetId(), p.name(), p.from(), p.to(), p.closed(), p.closedTotal(), totals, p.soft(), p.cap(),
                carried, p.personOpenings(), p.locked());
    }

    /** The period with each person's opening balance for it. */
    private Period withOpenings(Period p) {
        return new Period(p.sheetId(), p.name(), p.from(), p.to(), p.closed(), p.closedTotal(), p.personTotals(), p.soft(),
                p.cap(), p.personCarried(), openings(p.sheetId(), p.name()), p.locked());
    }

